namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    private readonly List<Notification> _notifications = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New feature: dark mode is now available."),
        });
    }

    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    public List<Notification> GetNotificationsSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally to generate fake data on a schedule.
    /// </summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "You have a new follower.",
            "Your build completed successfully.",
            "Reminder: standup in 15 minutes.",
            "Someone commented on your PR.",
            "Deployment to production finished.",
            "New security alert on your repository.",
        };

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message)
    {
        lock (_lock)
        {
            return new Notification(_nextId++, message, DateTime.UtcNow.AddSeconds(_nextId));
        }
    }
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background service that simulates new notifications arriving every ~8 seconds.
/// </summary>
public class NotificationSimulatorService : BackgroundService
{
    private readonly NotificationService _notificationService;

    public NotificationSimulatorService(NotificationService notificationService)
    {
        _notificationService = notificationService;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            _notificationService.SimulateIncoming();
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@notification.Message</div>
                <small class="text-muted">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorNotifications.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override void OnInitialized()
    {
        // Load initial notifications during prerender AND interactive init.
        // On prerender this populates the server-rendered HTML.
        // On interactive init this runs again but we need the data either way
        // to avoid a blank flash. The service returns from memory so it's cheap.
        _notifications = NotificationService.GetNotifications();
        _lastCheck = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires in interactive mode, never during static SSR.
            // This is where we safely start the polling loop.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

            var newOnes = NotificationService.GetNotificationsSince(_lastCheck);
            if (newOnes.Count > 0)
            {
                _notifications.InsertRange(0, newOnes);
                _lastCheck = newOnes.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

